  ui_story_5062_50620103_3_dialog_content = "Informe su situación actual.",
  ui_story_5062_50620103_4_dialog_content = "En el perímetro del área de la misión, preparándonos para entrar.",
  ui_story_5062_50620103_5_dialog_content = "Las comunicaciones están claras y los suministros son suficientes. Hasta ahora, todo bien... excepto...",
  ui_story_5062_50620103_6_dialog_content = "¿Excepto qué?",
  ui_story_5062_50620103_7_dialog_content = "Excepto Benny y Revy que han estado constantemente compitiendo entre sí por la oportunidad de luchar contra algunos Eclipsites.",
  ui_story_5062_50620103_8_dialog_content = "Son excelentes luchadores en cuanto a sus talentos individuales y la opción ideal para una misión de exploración a pequeña escala como esta.",
  ui_story_5062_50620103_9_dialog_content = "Pero nuestra oficial de inteligencia dice que son tan ruidosos que ¡ni siquiera puede dormir bien por la noche!",
  ui_story_5062_50620103_10_dialog_content = "Hmm... Cuando se trata de manejar información, nadie se le acerca ni de cerca a ella.",
  ui_story_5062_50620103_11_dialog_content = "Oh sí, y parece que hay algo extraño flotando alrededor de Chandra.",
  ui_story_5062_50620103_12_dialog_content = "El entorno de esta operación es especial. Por lo tanto, la asesoría psicológica es esencial para el personal de combate.",
  ui_story_5062_50620103_13_dialog_content = "En cuanto a otros problemas, pueden ser ignorados por ahora.",
  ui_story_5062_50620103_14_dialog_content = "Entendido. Entonces todas las cosas están bien.",
  ui_story_5062_50620103_15_dialog_content = "De acuerdo. Ahora déjame resumirte tu misión una vez más.",
  ui_story_5062_50620103_16_dialog_content = "Esta vez, comenzarás desde Crepúsculo, avanzando para explorar las fronteras de la noche eterna.",
  ui_story_5062_50620103_17_dialog_content = "Debemos monitorear la actividad de los Eclipsites lo más de cerca posible para prevenir otro ataque sorpresa.",
  ui_story_5062_50620103_18_dialog_content = "Entendido.",
  ui_story_5062_50620103_19_dialog_content = "Sincronizaré las coordenadas de los lugares de exploración de este plan contigo más tarde.",
  ui_story_5062_50620103_20_dialog_content = "En cuanto a cualquier situación imprevista, tendrás que recurrir a tu experiencia y adaptarte a la situación de manera adecuada.",
  ui_story_5062_50620103_21_dialog_content = "Pensar rápido en tus pies, mi tipo favorito.",
  ui_story_5062_50620103_22_dialog_content = "No olvides que esta es una misión de exploración. Solo haz tu trabajo de reconocimiento.",
  ui_story_5062_50620103_23_dialog_content = "Entonces, si nos encontramos con el enemigo, deberíamos guardar las hazañas heroicas para otro día y retirarnos de inmediato, ¿verdad?",
  ui_story_5062_50620103_24_dialog_content = "Sí. Estoy seguro de que podrás manejar cualquier situación que se te presente.",
  ui_story_5062_50620103_25_dialog_content = "¿¡Qué?! ¿¡Retirada?! ¿Por qué no simplemente los hacemos volar en pedazos! ¡Kaboom!",
  ui_story_5062_50620103_26_dialog_content = "Basta... ¿Todavía recuerdas el objetivo de la misión? No se supone que debemos—",
  ui_story_5062_50620103_27_dialog_content = "¿Qué tal una pequeña apuesta? ¡Veamos quién puede derribar a más Eclipsites! ¿Qué dices?!",
  ui_story_5062_50620103_28_dialog_content = "¡Oye! ¡No balancees tus armas así!",
  ui_story_5062_50620103_29_dialog_content = "¡Estás dentro! Kuro, cuenta para mí, ¿quieres?",
  ui_story_5062_50620103_30_dialog_content = "Lo siento, Capitán, mantendré a ambos bajo control...",
  ui_story_5062_50620103_31_dialog_content = "¡Permíteme asistirte!",
  ui_story_5062_50620103_32_dialog_content = "Benny, ¡no toques esa bolsa! ¡Esas son nuestras raciones!",
  ui_story_5062_50620103_33_dialog_content = "¿Mmm? ¿Escuché a alguien decir \"raciones\", miau?",
  ui_story_5062_50620103_34_dialog_content = "¡Pescado seco! ¡Pescado seco!",
  ui_story_5062_50620103_35_dialog_content = "¡No hay pescado seco aquí! Las raciones de combate deben ser altas en calorías. Todo lo que ves aquí fue preparado por mí mismo.",
  ui_story_5062_50620103_36_dialog_content = "Este olor... ¡Este olor! Maullar... ¿Podría ser...?",
  ui_story_5062_50620103_37_dialog_content = "Parece ser algún tipo de producto de queso.",
  ui_story_5062_50620103_38_dialog_content = "¡Queso! Ay, ¿por qué tiene que ser queso?! ¡Miau!",
  ui_story_5062_50620103_39_dialog_content = "Philyshy, ¡por favor no desperdicies nuestros suministros!",
  ui_story_5062_50620103_40_dialog_content = "¡Este equipo está lleno de vida! Me recuerda a aquellos días con las Fuerzas de Piedra.",
  ui_story_5062_50620103_41_dialog_content = "En aquel entonces, yo era como ellos ahora... Hmm, ¿cómo se dice... eso es—salvaje!",
  ui_story_5062_50620103_42_dialog_content = "Mantén contacto regular cada hora e informa al llegar al punto objetivo o si surge alguna otra situación.",
  ui_story_5062_50620103_43_dialog_content = "Está bien, ya repasamos todo esto lo suficientemente bien antes de la misión.",
  ui_story_5062_50620103_44_dialog_content = "Sabemos casi nada sobre lo que podría estar esperándonos más allá de la línea de defensa. Mantente alerta.",
  ui_story_5062_50620103_45_dialog_content = "Entendido. Solo desearía que pudiéramos terminar con esto en lugar de escucharte divagar una y otra vez...",
  ui_story_5062_50620103_46_dialog_content = "Haré todo lo posible para dejar mis viejos hábitos... No dejaré que lo que sucedió en aquel entonces vuelva a pasar.",
  ui_story_5062_50620103_47_dialog_content = "Lo siento por ponerte en esta misión. Es algo improvisado.",
  ui_story_5062_50620103_48_dialog_content = "Pocas personas son lo suficientemente competentes para ser enviadas a la frontera. Simplemente no tenía muchas opciones.",
  ui_story_5062_50620103_49_dialog_content = "Está bien. Soy un soldado. El campo de batalla es mi hogar.",
  ui_story_5062_50620103_50_dialog_content = "Y basta de charlas. A juzgar por la disminución de luz en el entorno, diría que hemos entrado en la zona de la misión.",
  ui_story_5062_50620103_51_dialog_content = "Mantén un ojo atento a los movimientos en tu entorno. Sincronizaré las coordenadas del primer punto objetivo contigo.",
  ui_story_5062_50620103_52_dialog_content = "Entendido.",
  ui_story_5062_50620103_53_dialog_content = "Señorita oficial de inteligencia, confirme su información sobre el punto objetivo, por favor.",
  ui_story_5062_50620103_54_dialog_content = "¿Cómo es que todavía tenemos que trabajar cuando ni siquiera tenemos pescado seco, miau...?",
  ui_story_5062_50620103_55_dialog_content = "Tengo visualización de la ubicación objetivo. Listo para comenzar la misión de exploración.",
  ui_story_5062_50620103_56_dialog_content = "¿Ya llegamos? ¡Déjame tomar la iniciativa entonces!",
  ui_story_5062_50620103_57_dialog_content = "¿¡Qué?! Si alguien va a ser capitán, ¡seré yo! ¿Qué tal si peleamos por ello?",
  ui_story_5062_50620103_58_dialog_content = "Obviamente, el Sr. Gram es el capitán... Curo, ¿no puedes detenerlos?",
  ui_story_5062_50620103_59_dialog_content = "No tengo nada que ver con esos idiotas...",
  ui_story_5062_50620103_60_dialog_content = "Gram, solo hay una cosa más.",
  ui_story_5062_50620103_61_dialog_content = "Adelante, Gran Mariscal.",
  ui_story_5062_50620103_62_dialog_content = "... Ser capitán de este escuadrón no es un trabajo fácil. Gracias."
}
return config
